css:
.jh-page{--ink:#17202a;--acc:#2563eb;--soft:#eff4ff;--line:#dbe3ee;--mute:#506070;max-width:720px;margin:0 auto;padding:0 20px 56px;background:#fff;color:var(--ink);font-family:var(--page-sans),sans-serif;font-size:16px;line-height:1.7;word-break:keep-all;overflow-wrap:break-word;box-sizing:border-box}
.jh-page *{box-sizing:border-box}
.jh-page a{color:var(--acc)}
.jh-page a:focus-visible{outline:3px solid var(--acc);outline-offset:3px;border-radius:2px}
.jh-top{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px 16px;padding:18px 0;border-bottom:1px solid var(--line)}
.jh-name{font-weight:700}
.jh-top nav{display:flex;flex-wrap:wrap;gap:4px 16px;font-size:14px}
.jh-top nav a{text-decoration:none;color:var(--mute);padding:4px 0}
.jh-top nav a:hover{color:var(--acc)}
.jh-hero{padding:64px 0 48px}
.jh-kicker,.jh-label{font-family:var(--page-mono),monospace;font-size:13px;letter-spacing:.04em;color:var(--acc);margin:0 0 12px}
.jh-hero h1{font-family:var(--page-display),var(--page-sans),sans-serif;font-size:clamp(30px,6.4vw,46px);line-height:1.2;letter-spacing:-.02em;margin:0 0 20px}
.jh-lead{font-size:18px;margin:0 0 32px;color:#2a3644}
.jh-proof{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:0}
.jh-proof div{border:1px solid var(--line);border-top:3px solid var(--acc);border-radius:8px;padding:14px;background:#fff}
.jh-proof dt{font-size:13px;color:var(--mute);line-height:1.4}
.jh-proof dd{margin:6px 0 0;font-family:var(--page-mono),monospace;font-size:22px;font-weight:700;color:var(--acc)}
.jh-sec{padding:48px 0;border-top:1px solid var(--line)}
.jh-sec h2{font-size:clamp(24px,4.6vw,30px);line-height:1.3;letter-spacing:-.01em;margin:0 0 12px}
.jh-takeaway{font-size:18px;font-weight:600;margin:0 0 24px;padding-left:14px;border-left:3px solid var(--acc)}
.jh-trio{display:grid;gap:12px;margin:0 0 28px}
.jh-trio div{background:var(--soft);border-radius:10px;padding:16px 18px}
.jh-trio div:last-child{background:#fff;border:1px solid var(--acc)}
.jh-trio h3{margin:0 0 4px;font-size:14px;color:var(--acc)}
.jh-trio p{margin:0}
.jh-fig,.jh-lat{margin:0;border:1px solid var(--line);border-radius:10px;padding:18px}
.jh-fig figcaption,.jh-lat figcaption{font-weight:600;font-size:14px;margin-bottom:10px}
.jh-fig svg,.jh-lat svg{display:block;width:100%;height:auto}
.s-bar0{fill:var(--line)}
.s-bar1{fill:var(--acc)}
.s-t{font-size:14px;font-weight:600;fill:#17202a}
.s-in{font-size:13px;fill:#17202a}
.s-b{font-size:14px;font-weight:700;fill:var(--acc)}
.s-n{font-size:12px;fill:#506070}
.jh-metrics{display:grid;gap:16px;margin-top:24px}
.jh-stats{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:0}
.jh-stats div{background:var(--soft);border-radius:10px;padding:16px}
.jh-stats dt{font-size:13px;color:var(--mute);line-height:1.45}
.jh-stats dd{margin:6px 0 0;font-family:var(--page-mono),monospace;font-size:28px;font-weight:700;color:var(--acc)}
.jh-note{color:var(--mute);font-size:15px;margin:20px 0 0}
.jh-grow{transform-origin:left center;animation:jh-grow .9s ease-out both}
@keyframes jh-grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
.jh-flow{list-style:none;padding:0;margin:24px 0 0;display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.jh-flow li{padding:8px 14px;border:1px solid var(--line);border-radius:999px;font-size:14px}
.jh-flow li+li::before{content:"→";margin-right:10px;color:var(--mute)}
.jh-flow li.gate{background:var(--acc);border-color:var(--acc);color:#fff;font-weight:600}
.jh-flow li.gate::before{color:#17202a}
.jh-tl{list-style:none;margin:0;padding:0 0 0 18px;border-left:2px solid var(--line)}
.jh-tl li{position:relative;padding:0 0 20px 8px;display:grid;gap:2px}
.jh-tl li::before{content:"";position:absolute;left:-25px;top:9px;width:10px;height:10px;border-radius:50%;background:#fff;border:2px solid var(--acc)}
.jh-tl time{font-family:var(--page-mono),monospace;font-size:13px;color:var(--acc)}
.jh-foot{border-top:1px solid var(--line);padding-top:20px;font-size:14px;color:var(--mute)}
@media(max-width:560px){.jh-hero{padding:40px 0 32px}.jh-proof{grid-template-columns:1fr}.jh-proof div{display:flex;justify-content:space-between;align-items:baseline;gap:12px}.jh-proof dd{margin:0}.jh-stats{grid-template-columns:1fr}.jh-sec{padding:36px 0}}
@media(prefers-reduced-motion:reduce){.jh-grow{animation:none}}
